namespace Trackwise.DbMigrator.Models;

/// <summary>
/// A real trailer or chassis from the company's vehicle register (Monday Admin &gt; SKYBEST VEHICLES).
/// Seeded by <c>TrailerSeeder</c>; generated by <c>monday-export/scripts/fleet.py</c>.
/// </summary>
public record FleetTrailerData
{
    /// <summary>The company's asset code (<c>C010715</c>), or the plate where the register has none.</summary>
    public required string Code { get; set; }

    /// <summary>Null for chassis registered by LTO MV file number only.</summary>
    public string? Plate { get; set; }

    /// <summary>A <c>TrailerType</c> name, e.g. <c>ContainerChassis</c> or <c>Flatbed</c>.</summary>
    public required string Type { get; set; }

    public string? Branch { get; set; }
    public bool IsActive { get; set; } = true;

    /// <summary>MV file number, alternate plates, supplier and purchase date - the trailer has no columns for them.</summary>
    public string? Notes { get; set; }

    public VehiclePaperData[] Papers { get; set; } = [];
}
